// masthead:block chrome
function(hook) {
  hook.ready(function() {
    var sidebar = document.querySelector('.sidebar');
    if (!sidebar) return;

    // Inject theme toggle pill
    var pill = document.createElement('div');
    pill.className = 'theme-toggle';
    pill.setAttribute('aria-label', 'Toggle theme');
    pill.onclick = toggleTheme;
    pill.innerHTML =
      '<span class="theme-toggle-option theme-toggle-sun">' +
        '<svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" stroke="currentColor" stroke-width="2" stroke-linecap="round">' +
          '<circle cx="12" cy="12" r="5"/>' +
          '<path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/>' +
        '</svg>' +
      '</span>' +
      '<span class="theme-toggle-option theme-toggle-moon">' +
        '<svg viewBox="0 0 24 24" width="14" height="14" fill="currentColor" stroke="currentColor" stroke-width="2" stroke-linecap="round">' +
          '<path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/>' +
        '</svg>' +
      '</span>' +
      '<span class="theme-toggle-indicator"></span>';

    // Build header: [app-name] [pill] on one row, search below.
    // `margin-left: auto` on the pill (set in CSS) handles the
    // right-alignment.
    var header = document.createElement('div');
    header.className = 'sidebar-header';
    var row = document.createElement('div');
    row.className = 'sidebar-header-row';
    var appName = sidebar.querySelector('.app-name-link');
    if (appName) {
      // The site's favicon doubles as the sidebar logo, so it has one source.
      var nameText = document.createElement('span');
      nameText.className = 'app-name-text';
      nameText.textContent = appName.textContent;
      var icon = document.createElement('img');
      icon.className = 'app-name-icon';
      icon.src = document.querySelector('link[rel="icon"]').getAttribute('href');
      icon.alt = '';
      appName.replaceChildren(icon, nameText);
      row.appendChild(appName);
    }
    row.appendChild(pill);
    header.appendChild(row);
    var search = sidebar.querySelector('.search');
    if (search) {
      // The plugin draws its clear icon off-center in a 26x24 box.
      var clearIcon = search.querySelector('.clear-button svg');
      if (clearIcon) clearIcon.setAttribute('viewBox', '0 0 24 24');
      header.appendChild(search);
    }
    sidebar.insertBefore(header, sidebar.firstChild);

    // Resize handle. Mouse events (not pointer events) — mouse is
    // simpler and the touch audience for a docs sidebar is ~0.
    // Disable the sidebar's CSS transition during drag so the width
    // follows the cursor 1:1 (otherwise it visibly lags).
    // Double-click to auto-fit the sidebar to its widest nav label.
    var handle = document.createElement('div');
    handle.className = 'sidebar-resize-handle';
    handle.setAttribute('aria-label', 'Resize sidebar');
    sidebar.appendChild(handle);

    var WIDTH_KEY = 'docsify-sidebar-width';
    var savedWidth = localStorage.getItem(WIDTH_KEY);
    if (savedWidth) document.documentElement.style.setProperty('--sidebar-width', savedWidth);

    handle.addEventListener('dblclick', function() {
      var nav = sidebar.querySelector('.sidebar-nav');
      if (!nav) return;
      sidebar.style.width = 'min-content';
      nav.style.whiteSpace = 'nowrap';
      var fitWidth = sidebar.offsetWidth + 20;
      sidebar.style.width = '';
      nav.style.whiteSpace = '';
      var w = Math.max(200, Math.min(fitWidth, window.innerWidth * 0.5));
      document.documentElement.style.setProperty('--sidebar-width', w + 'px');
      localStorage.setItem(WIDTH_KEY, w + 'px');
    });

    handle.addEventListener('mousedown', function(e) {
      e.preventDefault();
      handle.classList.add('dragging');
      sidebar.style.transition = 'none';
      document.body.style.cursor = 'col-resize';
      document.body.style.userSelect = 'none';
      function onMove(ev) {
        var w = Math.max(200, Math.min(ev.clientX, window.innerWidth * 0.5));
        document.documentElement.style.setProperty('--sidebar-width', w + 'px');
      }
      function onUp() {
        handle.classList.remove('dragging');
        sidebar.style.transition = '';
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
        localStorage.setItem(WIDTH_KEY, document.documentElement.style.getPropertyValue('--sidebar-width'));
        document.removeEventListener('mousemove', onMove);
        document.removeEventListener('mouseup', onUp);
      }
      document.addEventListener('mousemove', onMove);
      document.addEventListener('mouseup', onUp);
    });
  });
  hook.doneEach(function() {
    if (typeof mermaid !== 'undefined') {
      mermaid.initialize({ startOnLoad: false, theme: getMermaidTheme(), look: 'handDrawn' });
      mermaid.run({ querySelector: '.mermaid' });
    }
  });
},

