blocks.1ef20607e14fdb0f:
/* masthead:block alerts */
/* ── Annotation callout colors ─────────────────────────── */
.markdown-section .tip {
  border-left-color: var(--notice-tip-border-color);
}
.markdown-section .warn,
.markdown-section .warning {
  border-left-color: var(--notice-warning-border-color);
}
.markdown-section .alert.callout.note      { --alert-color: var(--alert-note-color); }
.markdown-section .alert.callout.tip       { --alert-color: var(--alert-tip-color); }
.markdown-section .alert.callout.important { --alert-color: var(--alert-important-color); }
.markdown-section .alert.callout.warning   { --alert-color: var(--alert-warning-color); }
.markdown-section .alert.callout.attention { --alert-color: var(--alert-caution-color); }
/* :is() makes these more specific than the plugin's own
   .alert.callout.<type> rules. */
.markdown-section .alert.callout:is(.note, .tip, .important, .warning, .attention) {
  border-left-color: var(--alert-color) !important;
}
.markdown-section .alert.callout:is(.note, .tip, .important, .warning, .attention) .title {
  color: var(--alert-color);
}

blocks.278a41a3b683f212:
// masthead:block mermaid-links
// docsify scrolls to a ?id= heading only when the click's target, or
// its parent, has tagName 'A'. A mermaid `click` link is an SVG <a>
// (tagName 'a') around a label <p>, so docsify takes the hash change
// for back or forward and leaves the page where it is. Replay the
// click on an HTML link so docsify sees a link navigation.
function mermaidLinks(hook) {
  hook.mounted(function () {
    document.addEventListener('click', function (e) {
      var svgLink = e.target.closest('.mermaid a');
      // A modified click or a link with a target keeps the browser's own handling.
      if (!svgLink || e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
      var target = svgLink.getAttribute('target');
      if (target && target !== '_self') return;
      e.preventDefault();
      var link = document.createElement('a');
      link.href = svgLink.getAttribute('xlink:href') || svgLink.getAttribute('href');
      document.body.appendChild(link);
      link.click();
      link.remove();
    });
  });
},

