// masthead:block deep-link-settle
// docsify measures a ?id= target once, before the mermaid diagrams and
// images above it reach their rendered size, so a deep link lands short
// by their combined height. Once they have, and docsify's own scroll
// animation has stopped, scroll to the target again.
function deepLinkSettle(hook) {
  var MAX_FRAMES = 600;
  // docsify's ?id= tween runs this long. scrollY can't say when it's
  // done: it eases out, holding still for frames before its last
  // write, and one aimed past the top or bottom writes a clamped
  // value that never moves.
  var DOCSIFY_SCROLL_MS = 500;
  hook.doneEach(function () {
    var match = /[?&]id=([^&]+)/.exec(location.hash);
    if (!match) return;
    var id = decodeURIComponent(match[1]);
    var frames = 0, stillFrames = 0, lastY = -1, started = performance.now();
    (function settle() {
      if (++frames > MAX_FRAMES) return;
      var target = document.getElementById(id);
      var above = function (el) {
        return target.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_PRECEDING;
      };
      var rendering = target && ([].some.call(document.querySelectorAll('.markdown-section .mermaid'), function (el) {
        return above(el) && !el.querySelector('svg');
      }) || [].some.call(document.querySelectorAll('.markdown-section img'), function (img) {
        if (!above(img) || img.complete) return false;
        // A lazy image far above the viewport (docsify's emoji) never
        // loads on its own, so it would hold the correction until the cap.
        img.loading = 'eager';
        return true;
      }));
      stillFrames = window.scrollY === lastY ? stillFrames + 1 : 0;
      lastY = window.scrollY;
      var tweening = performance.now() - started < DOCSIFY_SCROLL_MS;
      if (!target || rendering || tweening || stillFrames < 3) return requestAnimationFrame(settle);
      var offset = target.getBoundingClientRect().top - (window.$docsify.topMargin || 0);
      if (Math.abs(offset) > 2) window.scrollTo(0, window.scrollY + offset);
    })();
  });
},

