/* masthead:block element-overrides */
/* ── Element overrides the theme doesn't cover ───────── */
.markdown-section {
  color: var(--base-color);
}
/* Heading scale: docsify-themeable shrinks h5/h6 below body size
   (h6 ≈ 9px), which makes deeply-nested headings unreadable — e.g. a
   catalog nesting tier > team > plugin lands real headings at h5/h6.
   Enforce a scale that steps down but never drops below body, and size
   backticked names relative to their heading rather than the small global
   code size. */
.markdown-section h3 { font-size: 1.5rem; }
.markdown-section h4 { font-size: 1.25rem; }
.markdown-section h5 { font-size: 1.1rem; }
.markdown-section h6 { font-size: 1rem; }
.markdown-section h1 code, .markdown-section h2 code,
.markdown-section h3 code, .markdown-section h4 code,
.markdown-section h5 code, .markdown-section h6 code {
  font-size: 0.9em;
}
.markdown-section table tr {
  color: var(--base-color);
}
.markdown-section table tr:nth-child(2n) {
  background-color: var(--table-row-even-background);
}
.markdown-section table tr:nth-child(2n+1) {
  background-color: var(--table-row-odd-background);
}
.markdown-section table th {
  color: var(--table-header-color);
  background-color: var(--table-header-background);
}
/* Browsers break an ISO date after its hyphens once a wide neighbour
   squeezes the column, so a date in a <time> stays on one line. */
.markdown-section time { white-space: nowrap; }
.markdown-section code {
  color: var(--code-inline-color);
  background-color: var(--code-inline-background);
}
.markdown-section pre code {
  color: var(--code-theme-text);
  background-color: var(--code-theme-background);
}
.markdown-section .token.comment,
.markdown-section .token.prolog,
.markdown-section .token.doctype      { color: var(--code-token-comment); }
.markdown-section .token.key,
.markdown-section .token.property,
.markdown-section .token.attr-name,
.markdown-section .token.tag          { color: var(--code-token-key); }
.markdown-section .token.keyword,
.markdown-section .token.atrule,
.markdown-section .token.important,
.markdown-section .token.selector     { color: var(--code-token-keyword); }
.markdown-section .token.string,
.markdown-section .token.char,
.markdown-section .token.attr-value   { color: var(--code-token-string); }
.markdown-section .token.number,
.markdown-section .token.boolean,
.markdown-section .token.constant     { color: var(--code-token-number); }
.markdown-section .token.function,
.markdown-section .token.class-name,
.markdown-section .token.builtin,
.markdown-section .token.inserted     { color: var(--code-token-function); }
.markdown-section .token.deleted      { color: var(--code-token-deleted); }
.markdown-section .token.variable,
.markdown-section .token.interpolation,
.markdown-section .token.regex        { color: var(--code-token-variable); }
.markdown-section .token.punctuation,
.markdown-section .token.operator,
.markdown-section .token.scalar,
.markdown-section .token.entity,
.markdown-section .token.url          { color: var(--code-token-punctuation); }
/* Mermaid's dark theme sets labels to #ccc, which is 4.4:1 on its own
   #585858 edge-label fill. Its rules are scoped by the SVG's id. */
.mermaid :is(.nodeLabel, .edgeLabel, .cluster-label) { color: var(--base-color) !important; }
/* A hand-drawn node is two paths: the hatch fill, then the outline. */
.mermaid .highlight .label-container > path:first-child { stroke: var(--diagram-highlight-fill); }
.mermaid .highlight .label-container > path:last-child  { stroke: var(--diagram-highlight-stroke); }
/* Long lines soft-wrap at whitespace (word boundaries) only — never
   mid-token — so a command like `... add <URL>` breaks after `add` and the
   URL stays intact on the next line rather than splitting mid-character.
   Put `white-space: pre-wrap` on BOTH the `pre` and the inner `code`:
   theme-simple-dark sets `nowrap` on inline `code` (which also matches
   `pre > code`), so the inner rule is needed. Leave overflow-wrap at its
   default `normal` — `anywhere`/`break-word` would break the URL
   mid-character. Soft-wrap is copy-safe: textContent carries no inserted
   breaks, so docsify-copy-code still yields the verbatim line. */
.markdown-section pre,
.markdown-section pre > code {
  white-space: pre-wrap !important;
}
/* Opt-in atomic run: wrap an argument (a URL, a url-mapping) in
   <span class="nowrap"> so the line breaks at the space *before* it and
   the run stays whole, rather than splitting mid-token. See the "forcing a
   break at a chosen point" note in references/docsify-template.md. The span doesn't change textContent, so
   the copy button still yields the verbatim line. */
.markdown-section pre code .nowrap {
  white-space: nowrap;
}
/* Inline code wraps like text: theme-simple-dark's `nowrap` runs a long
   one out of its table cell or callout. It breaks at spaces, and
   mid-token (the theme's overflow-wrap) when one token is wider than the
   line. Same selector as the theme's; this sheet loads after it. */
.markdown-section code:not([class*=lang-]):not([class*=language-]) {
  white-space: normal;
}
/* Hanging indent for the wrapped continuation line of a forced-break
   command: the first line sits at the gutter, the wrapped argument is
   inset a couple of chars so it reads as a continuation. Scoped to
   `:has(.nowrap)` so it never shifts the lines of a normal multi-line
   code block (where every line after the first would otherwise indent). */
.markdown-section pre:has(.nowrap) > code {
  display: block;
  padding-left: 2ch;
  text-indent: -2ch;
}

