// masthead:block page-toc
// The page-contents rail: a row for each h2 to h4 on the page, linking
// to #/<route>?id=<id> so docsify scrolls to it as it does for any
// heading link. A row is labelled from a clone of its heading with
// injected tools removed, never from the heading's HTML: a heading
// whose text is a link would put that outbound link in the rail.
// Rows indent by nesting, not by tag level, so an h4 straight under an
// h2 sits one step in. The highlighted row is the last heading whose
// top has passed the top of the window. `pageToc: false` in $docsify
// turns the rail off; a page that re-renders its headings dispatches
// `masthead:content-changed` on document to rebuild it.
function pageToc(hook) {
  var MIN_ROWS = 2;
  var rail = null, rows = [], scheduled = false;
  function highlight() {
    scheduled = false;
    if (!rows.length) return;
    var line = (window.$docsify.topMargin || 0) + 8;
    var current = rows[0];
    for (var i = 0; i < rows.length; i++) {
      if (rows[i].heading.getBoundingClientRect().top > line + 1) break;
      current = rows[i];
    }
    rows.forEach(function (row) { row.link.classList.toggle('active', row === current); });
    // Keep the highlighted row in view inside the rail, never by scrolling the page.
    var top = current.link.offsetTop, bottom = top + current.link.offsetHeight;
    if (top < rail.scrollTop) rail.scrollTop = top - 8;
    else if (bottom > rail.scrollTop + rail.clientHeight) rail.scrollTop = bottom - rail.clientHeight + 8;
  }
  function schedule() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(highlight);
  }
  function build() {
    if (rail) rail.remove();
    rail = null;
    rows = [];
    document.body.classList.remove('has-page-toc');
    if (window.$docsify.pageToc === false) return;
    var route = location.hash.split('?')[0] || '#/';
    var stack = [];
    var entries = [];
    document.querySelectorAll('.markdown-section h2[id], .markdown-section h3[id], .markdown-section h4[id]').forEach(function (heading) {
      var label = heading.cloneNode(true);
      label.querySelectorAll('button, svg, [aria-hidden="true"]').forEach(function (el) { el.remove(); });
      var text = label.textContent.trim();
      if (!text) return;
      var level = Number(heading.tagName.charAt(1));
      while (stack.length && stack[stack.length - 1] >= level) stack.pop();
      entries.push({ heading: heading, text: text, depth: stack.length });
      stack.push(level);
    });
    if (entries.length < MIN_ROWS) return;
    rail = document.createElement('nav');
    rail.className = 'page-toc';
    rail.setAttribute('aria-label', 'On this page');
    var title = document.createElement('p');
    title.className = 'page-toc-title';
    title.textContent = 'On this page';
    rail.appendChild(title);
    entries.forEach(function (entry) {
      var link = document.createElement('a');
      link.href = route + '?id=' + encodeURIComponent(entry.heading.id);
      link.textContent = entry.text;
      link.style.setProperty('--depth', entry.depth);
      rail.appendChild(link);
      rows.push({ heading: entry.heading, link: link });
    });
    document.body.appendChild(rail);
    document.body.classList.add('has-page-toc');
    highlight();
  }
  hook.doneEach(build);
  hook.mounted(function () {
    window.addEventListener('scroll', schedule, { passive: true });
    window.addEventListener('resize', schedule);
    document.addEventListener('masthead:content-changed', build);
  });
}

blocks.a0ca71983e75ef24:
/* masthead:block copy-button */
/* ── Copy button ───────────────────────────────────────
   docsify-copy-code ships a hard-cornered label block pinned to the
   panel corner that, on success, slides a "Copied" word out to its left.
   Restyle it to a compact clipboard-icon button that flips to a green
   check on copy, then reverts. The plugin toggles `.success`/`.error` on
   the button and reveals it on `pre:hover` (and keyboard `:focus`); all
   visuals key off those states.
   Scoped under `.markdown-section` to outrank the plugin's own single-
   class rules regardless of stylesheet insertion order. */
.markdown-section .docsify-copy-code-button {
  top: 8px;
  right: 8px;
  width: 30px;
  height: 30px;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 6px;
  background: var(--copy-btn-bg);
  opacity: 0;
  transition: opacity 0.2s ease, background 0.2s ease;
}
.markdown-section pre:hover .docsify-copy-code-button,
.markdown-section .docsify-copy-code-button:focus {
  opacity: 1;
}
/* Hide docsify-themeable's language label (pre[data-lang]::after). It
   shares the top-right corner with the copy button and adds little, so
   the corner belongs to the button alone. */
.markdown-section pre[data-lang]::after {
  display: none;
}
.markdown-section .docsify-copy-code-button:hover {
  background: var(--copy-btn-bg-hover);
}
/* Hide the plugin's text spans (label + slide-out "Copied"/"Error"). */
.markdown-section .docsify-copy-code-button span { display: none; }
/* Icon painted on the button via a mask so state changes recolor it. */
.markdown-section .docsify-copy-code-button::after {
  content: "";
  width: 15px;
  height: 15px;
  background-color: var(--copy-btn-fg);
  -webkit-mask: var(--icon-clipboard) center / contain no-repeat;
          mask: var(--icon-clipboard) center / contain no-repeat;
  transition: background-color 0.2s ease;
}
/* Success: button + icon go green, check replaces clipboard, stays lit. */
.markdown-section .docsify-copy-code-button.success {
  opacity: 1;
  background: var(--copy-btn-success-bg);
}
.markdown-section .docsify-copy-code-button.success::after {
  background-color: var(--copy-btn-success-fg);
  -webkit-mask-image: var(--icon-check);
          mask-image: var(--icon-check);
}

