blocks.f7b20e4521610781:
// masthead:block svg-links
// docsify scrolls to a ?id= target only for a click it saw land on an
// HTML link: it tests tagName === 'A', and a link inside an SVG reports
// 'a'. A chart whose rows link to entries on the same page (an SVG
// timeline, say) would change the URL and stay put without this.
function svgLinks(hook) {
  hook.mounted(function () {
    document.addEventListener('click', function (e) {
      var link = e.target.closest && e.target.closest('.markdown-section svg a');
      if (!link || link.getAttribute('target')) return;
      var m = /^#([^?]*)\?(?:[^#]*&)?id=([^&]+)/.exec(link.getAttribute('href') || '');
      if (!m || location.hash.split('?')[0] !== '#' + m[1]) return;
      var target = document.getElementById(decodeURIComponent(m[2]));
      if (!target) return;
      e.preventDefault();
      location.hash = link.getAttribute('href');
      var top = window.scrollY + target.getBoundingClientRect().top - (window.$docsify.topMargin || 0);
      window.scrollTo({ top: top, behavior: 'smooth' });
    });
  });
},
